    //=============================================================================
// Module:      alu
// Description: 32-bit ALU with registered outputs, synchronous active-high
//              reset, and four status flags (zero, overflow, negative).
//
//   Opcodes:
//     0000 : ADD   result = A + B (mod 2^32), signed overflow reported
//     0001 : SUB   result = A - B (mod 2^32), signed overflow reported
//     0010 : AND   result = A & B
//     0011 : OR    result = A | B
//     0100 : XOR   result = A ^ B
//     0101 : SLL   result = A << B[4:0]
//     0110 : SRL   result = A >> B[4:0]  (zero fill)
//     0111 : SRA   result = A >>> B[4:0] (sign fill)
//     1000 : SLT   result = 32'd1 if $signed(A) < $signed(B) else 32'd0
//     1001 : SLTU  result = 32'd1 if A < B (unsigned) else 32'd0
//
//   Flags (registered, aligned with the registered result):
//     zero     : result == 32'b0
//     overflow : signed two's-complement overflow (ADD/SUB only, else 0)
//     negative : result[31]
//
//   Verilog-2001, fully synthesizable. Barrel shifters are unrolled
//   explicitly into five stages so that all part-selects and replication
//   counts are compile-time constants.
//=============================================================================

module alu (
    input  wire        clk,
    input  wire        rst,
    input  wire [31:0] a,
    input  wire [31:0] b,
    input  wire [3:0]  opcode,
    output reg  [31:0] result,
    output reg         zero,
    output reg         overflow,
    output reg         negative
);

    //------------------------------------------------------------------
    // Combinational operation results
    //------------------------------------------------------------------
    reg [31:0] temp_result;
    reg        temp_overflow;

    // Barrel-shifter stage registers (5 stages for a 32-bit operand).
    reg [31:0] shift_s1;
    reg [31:0] shift_s2;
    reg [31:0] shift_s3;
    reg [31:0] shift_s4;
    reg [31:0] shift_s5;

    //------------------------------------------------------------------
    // Combinational ALU core
    //------------------------------------------------------------------
    always @(*) begin
        // Safe defaults
        temp_result   = 32'b0;
        temp_overflow = 1'b0;

        // Shift pipeline defaults (overwritten in the shift branches)
        shift_s1 = a;
        shift_s2 = a;
        shift_s3 = a;
        shift_s4 = a;
        shift_s5 = a;

        case (opcode)

            //----------------------------------------------------------
            // ADD: A + B modulo 2^32; signed overflow detection
            //----------------------------------------------------------
            4'b0000: begin
                temp_result   = a + b;
                temp_overflow = (a[31] &  b[31] & ~temp_result[31]) |
                                (~a[31] & ~b[31] &  temp_result[31]);
            end

            //----------------------------------------------------------
            // SUB: A - B modulo 2^32; signed overflow detection
            //----------------------------------------------------------
            4'b0001: begin
                temp_result   = a - b;
                temp_overflow = (a[31] & ~b[31] & ~temp_result[31]) |
                                (~a[31] &  b[31] &  temp_result[31]);
            end

            //----------------------------------------------------------
            // AND
            //----------------------------------------------------------
            4'b0010: temp_result = a & b;
            4'b0011: temp_result = a | b;
            4'b0100: temp_result = a ^ b;
            4'b0101: begin
                // Stage 0: shift by 1 if B[0]
                shift_s1 = b[0] ? {a[30:0], 1'b0} : a;
                // Stage 1: shift by 2 if B[1]
                shift_s2 = b[1] ? {shift_s1[29:0], 2'b00} : shift_s1;
                // Stage 2: shift by 4 if B[2]
                shift_s3 = b[2] ? {shift_s2[27:0], 4'b0000} : shift_s2;
                // Stage 3: shift by 8 if B[3]
                shift_s4 = b[3] ? {shift_s3[23:0], 8'h00} : shift_s3;
                // Stage 4: shift by 16 if B[4]
                shift_s5 = b[4] ? {shift_s4[15:0], 16'h0000} : shift_s4;
                temp_result = shift_s5;
            end

            //----------------------------------------------------------
            // SRL: logical right shift by B[4:0], zero fill
            //----------------------------------------------------------
            4'b0110: begin
                // Stage 0: shift by 1 if B[0]
                shift_s1 = b[0] ? {1'b0, a[31:1]} : a;
                // Stage 1: shift by 2 if B[1]
                shift_s2 = b[1] ? {2'b00, shift_s1[31:2]} : shift_s1;
                // Stage 2: shift by 4 if B[2]
                shift_s3 = b[2] ? {4'b0000, shift_s2[31:4]} : shift_s2;
                // Stage 3: shift by 8 if B[3]
                shift_s4 = b[3] ? {8'h00, shift_s3[31:8]} : shift_s3;
                // Stage 4: shift by 16 if B[4]
                shift_s5 = b[4] ? {16'h0000, shift_s4[31:16]} : shift_s4;
                temp_result = shift_s5;
            end

            //----------------------------------------------------------
            // SRA: arithmetic right shift by B[4:0], sign fill
            //      Sign bit is always A[31] (constant replication source)
            //----------------------------------------------------------
            4'b0111: begin
                // Stage 0: shift by 1 if B[0]
                shift_s1 = b[0] ? {a[31], a[31:1]} : a;
                // Stage 1: shift by 2 if B[1]
                shift_s2 = b[1] ? {{2{a[31]}}, shift_s1[31:2]} : shift_s1;
                // Stage 2: shift by 4 if B[2]
                shift_s3 = b[2] ? {{4{a[31]}}, shift_s2[31:4]} : shift_s2;
                // Stage 3: shift by 8 if B[3]
                shift_s4 = b[3] ? {{8{a[31]}}, shift_s3[31:8]} : shift_s3;
                // Stage 4: shift by 16 if B[4]
                shift_s5 = b[4] ? {{16{a[31]}}, shift_s4[31:16]} : shift_s4;
                temp_result = shift_s5;
            end

            //----------------------------------------------------------
            // SLT: signed set-less-than -> 32'd1 or 32'd0
            //----------------------------------------------------------
            4'b1000: begin
                temp_result = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
            end

            //----------------------------------------------------------
            // SLTU: unsigned set-less-than -> 32'd1 or 32'd0
            //----------------------------------------------------------
            4'b1001: begin
                temp_result = (a < b) ? 32'd1 : 32'd0;
            end

            //----------------------------------------------------------
            // Default: result cleared, no overflow
            //----------------------------------------------------------
            default: begin
                temp_result   = 32'b0;
                temp_overflow = 1'b0;
            end

        endcase
    end

    //------------------------------------------------------------------
    // Sequential output registers (synchronous active-high reset)
    //------------------------------------------------------------------
    always @(posedge clk) begin
        if (rst) begin
            result   <= 32'b0;
            zero     <= 1'b0;
            overflow <= 1'b0;
            negative <= 1'b0;
        end else begin
            result   <= temp_result;
            zero     <= (temp_result == 32'b0);
            overflow <= temp_overflow;
            negative <= temp_result[31];
        end
    end

endmodule